import sys

def main():
    line_input = sys.stdin.readline().rstrip('\n')
    s_chars = list(line_input)
    found_x = False
    length = len(s_chars)
    for ch in s_chars:
        if ch == 'X':
            found_x = True

    total_count = 0
    for digit in range(10):
        temp_chars = []
        for ch in s_chars:
            if ch == 'X':
                temp_chars.append(str(digit))
            else:
                temp_chars.append(ch)
        if temp_chars[0] == '0':
            continue

        dp_array = [[0] * 25 for _ in range(2)]
        current_idx = 1
        dp_array[0][0] = 1
        for i in range(length):
            for j in range(25):
                dp_array[current_idx][j] = 0
            low_bound = 0
            high_bound = 9
            if temp_chars[i] != '_':
                low_bound = high_bound = int(temp_chars[i])
            elif i == 0:
                low_bound += 1

            for prev_mod in range(25):
                for digit_val in range(low_bound, high_bound + 1):
                    next_val = (prev_mod * 10 + digit_val) % 25
                    dp_array[current_idx][next_val] += dp_array[current_idx ^ 1][prev_mod]
            current_idx ^= 1
        total_count += dp_array[current_idx ^ 1][0]
        if not found_x:
            break

    if length == 1 and (s_chars[0] == '_' or s_chars[0] == 'X' or s_chars[0] == '0'):
        total_count += 1
    print(total_count)

if __name__ == "__main__":
    main()

